#!/usr/bin/env node
// make contracts: packages/contracts/*.schema.json -> TS (@trophy/contracts) + Pydantic v2 (py-trophy).
// Generated files are committed; CI re-runs this and fails on any diff (codegen staleness).
import { execFileSync } from "node:child_process";
import { readdirSync, readFileSync, writeFileSync, mkdirSync, rmSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { compile } from "json-schema-to-typescript";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const schemaDir = join(root, "packages/contracts");
const tsOut = join(schemaDir, "gen/ts");
const pyProject = join(root, "packages/py-trophy");
const pyOut = join(pyProject, "trophy/contracts");

const schemas = readdirSync(schemaDir)
  .filter((f) => f.endsWith(".schema.json"))
  .sort();

const lf = (s) => s.replace(/\r\n/g, "\n");

// ---- TypeScript ----
rmSync(tsOut, { recursive: true, force: true });
mkdirSync(tsOut, { recursive: true });
const tsModules = [];
for (const file of schemas) {
  const name = file.replace(".schema.json", "");
  const schema = JSON.parse(readFileSync(join(schemaDir, file), "utf8"));
  const ts = await compile(schema, schema.title, {
    bannerComment: `/* Generated by \`make contracts\` from packages/contracts/${file}. Do not edit. */`,
    unreachableDefinitions: true,
    additionalProperties: false,
    declareExternallyReferenced: true,
    format: true,
    style: { printWidth: 120 },
    cwd: schemaDir,
  });
  writeFileSync(join(tsOut, `${name}.ts`), lf(ts));
  tsModules.push(name);
}
const index =
  "/* Generated by `make contracts`. Do not edit. */\n" +
  tsModules.map((m) => `export type * from "./${m}.ts";`).join("\n") +
  "\n";
writeFileSync(join(tsOut, "index.ts"), index);

// ---- Python (pydantic v2) ----
mkdirSync(pyOut, { recursive: true });
for (const f of readdirSync(pyOut)) if (f.endsWith(".py")) rmSync(join(pyOut, f));
const exportsByModule = {};
for (const file of schemas) {
  const name = file.replace(".schema.json", "");
  const out = join(pyOut, `${name}.py`);
  execFileSync(
    "uv",
    [
      "run",
      "--project",
      pyProject,
      "--frozen",
      "datamodel-codegen",
      "--input",
      join(schemaDir, file),
      "--input-file-type",
      "jsonschema",
      "--output",
      out,
      "--output-model-type",
      "pydantic_v2.BaseModel",
      "--target-python-version",
      "3.11",
      "--use-title-as-name",
      "--collapse-root-models",
      "--use-schema-description",
      "--field-constraints",
      "--use-standard-collections",
      "--use-union-operator",
      "--use-double-quotes",
      "--enum-field-as-literal",
      "all",
      "--extra-fields",
      "allow",
      "--allow-population-by-field-name",
      "--disable-timestamp",
      "--formatters",
      "ruff-format",
    ],
    { stdio: ["ignore", "inherit", "inherit"], cwd: root },
  );
  // Normalise the header so output doesn't depend on the absolute path or OS.
  const py = lf(readFileSync(out, "utf8")).replace(/^#   filename:.*$/m, `#   filename:  ${file}`);
  writeFileSync(out, py);
  const schema = JSON.parse(readFileSync(join(schemaDir, file), "utf8"));
  const titles = [schema.title, ...Object.values(schema.$defs ?? {}).map((d) => d.title)].filter(
    (t) => t && new RegExp(`^class ${t}\\b|^${t} = `, "m").test(py),
  );
  exportsByModule[name] = titles;
}
const seen = new Map();
for (const [mod, names] of Object.entries(exportsByModule))
  for (const n of names) {
    if (seen.has(n)) throw new Error(`contract name collision: ${n} in ${seen.get(n)} and ${mod}`);
    seen.set(n, mod);
  }
const init =
  '"""Generated by `make contracts` from packages/contracts/*.schema.json. Do not edit."""\n\n' +
  Object.entries(exportsByModule)
    .map(([mod, names]) => `from .${mod} import ${names.join(", ")}`)
    .join("\n") +
  "\n\n__all__ = [\n" +
  [...seen.keys()]
    .sort()
    .map((n) => `    "${n}",`)
    .join("\n") +
  "\n]\n";
writeFileSync(join(pyOut, "__init__.py"), init);
execFileSync("uv", ["run", "--project", pyProject, "--frozen", "ruff", "format", pyOut], {
  stdio: ["ignore", "ignore", "inherit"],
  cwd: root,
});
console.log(`contracts: ${schemas.length} schemas -> ${tsOut} and ${pyOut}`);
